/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const taskType = api.context.props.taskType;
    if (taskType && taskType.toUpperCase() == 'COLLABORATIONTASKS')
        return helpers.translateSync("You can view all collaborations and start new ones in the collaborate side panel.");
    else if (taskType && taskType.toUpperCase() == 'ADHOCTASKS')
        return helpers.translateSync("These are created separately from the pre-defined communication/ collaboration plans.");
    else
        return helpers.translateSync("You can view all communications and create new ones in the communicate tab.");
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const upcomingTasks = (api.state) ? api.state.upcomingTasks : [];
    const overDueTasks = (api.state) ? api.state.overDueTasks : [];
    const pageLoaded = (api.state) ? api.state.pageLoaded : false;
    const dataFetchFailed = (api.state) ? api.state.dataFetchFailed : false;
    if ((upcomingTasks.length == 0 && overDueTasks.length == 0 && pageLoaded) || dataFetchFailed)
        return false;
    return true;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const dataFetchFailed = api.state.dataFetchFailed;
    const taskType = api.context.props.taskType;
    if (dataFetchFailed)
        return helpers.translateSync("An error occurred. Please contact your Admin for more information.");
    else if (taskType && taskType.toUpperCase() == 'COLLABORATIONTASKS')
        return helpers.translateSync("Start collaborating with your team to work towards a resolution.");
    else if (taskType && taskType.toUpperCase() == 'COMMUNICATIONTASKS')
        return helpers.translateSync("Create communication tasks to let users know about an ongoing major incident.");
    else
        return helpers.translateSync("Start a new communication from communicate tab. Navigate to the Collaborate side panel to start a new call or chat.");
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let heading = {};
    const dataFetchFailed = (api.state) ? api.state.dataFetchFailed : false;
    let taskType = api.context.props.taskType;
    if (taskType && taskType.toUpperCase() == 'COLLABORATIONTASKS')
        taskType = "collaborations";
    else
        taskType = "communications";
    if (dataFetchFailed)
        heading.label = helpers.translateSync("No results found");
    else
        heading.label = helpers.translateSync("No {0} due", taskType);
    heading.level = "3";
    return heading;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    return helpers.translateSync("Active ({0})", [api.state.activeTasks.length]);
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    return helpers.translateSync("Overdue ({0})", [api.state.overDueTasks.length]);
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    return helpers.translateSync("Upcoming ({0})", [api.state.upcomingTasks.length]);

}
